import { Component, signal, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ExportImportDataService, UserRole } from './services/export-import-data.service';

// Public Home Portal Component
import { PublicHomeComponent } from './components/public-home/public-home.component';

// ERP Internal Modules
import { ErpDashboardComponent } from './components/erp-dashboard/erp-dashboard.component';
import { RoleManagementComponent } from './components/role-management/role-management.component';
import { ProductManagementComponent } from './components/product-management/product-management.component';
import { SupplierManagementComponent } from './components/supplier-management/supplier-management.component';
import { ImportManagementComponent } from './components/import-management/import-management.component';
import { ShipmentTrackerComponent } from './components/shipment-tracker/shipment-tracker.component';
import { CustomsDocsComponent } from './components/customs-docs/customs-docs.component';
import { WarehouseInventoryComponent } from './components/warehouse-inventory/warehouse-inventory.component';
import { ExportManagementComponent } from './components/export-management/export-management.component';
import { AccountsCostingComponent } from './components/accounts-costing/accounts-costing.component';
import { RfqCalculatorComponent } from './components/rfq-calculator/rfq-calculator.component';

export type AdminSidebarTab = 
  | 'dashboard'
  | 'roles' 
  | 'products' 
  | 'suppliers' 
  | 'imports' 
  | 'shipments' 
  | 'customs' 
  | 'warehouse' 
  | 'exports' 
  | 'accounts'
  | 'calculator';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [
    CommonModule,
    PublicHomeComponent,
    ErpDashboardComponent,
    RoleManagementComponent,
    ProductManagementComponent,
    SupplierManagementComponent,
    ImportManagementComponent,
    ShipmentTrackerComponent,
    CustomsDocsComponent,
    WarehouseInventoryComponent,
    ExportManagementComponent,
    AccountsCostingComponent,
    RfqCalculatorComponent
  ],
  template: `
    <div class="min-h-screen bg-slate-50 text-slate-900 selection:bg-emerald-500 selection:text-slate-950">

      <!-- View 1: Keya Group Public Sourcing & B2B Trade Home Page -->
      @if (currentView() === 'PUBLIC') {
        <app-public-home (onOpenAdmin)="currentView.set('ADMIN')"></app-public-home>
      }

      <!-- View 2: Separate Internal Keya Group ERP Admin Panel Workspace -->
      @if (currentView() === 'ADMIN') {
        <div class="flex overflow-hidden h-screen">

          <!-- Fixed Left Admin Sidebar -->
          <aside class="w-64 bg-slate-900 border-r border-slate-800 flex flex-col justify-between shrink-0 h-screen sticky top-0 text-slate-200">

            <div class="p-4 space-y-5 overflow-y-auto">

              <!-- ERP App Header Branding -->
              <div class="flex items-center gap-3 px-2 py-1">
                <div class="w-8 h-8 rounded-lg bg-emerald-600 flex items-center justify-center font-black text-white text-base shadow">
                  K
                </div>
                <div>
                  <h1 class="font-extrabold text-sm text-white tracking-wide">KEYA ERP ADMIN</h1>
                  <p class="text-[10px] text-slate-400 font-mono">Back-Office Operations</p>
                </div>
              </div>

              <!-- Return to Public Home Page Button -->
              <button 
                (click)="currentView.set('PUBLIC')"
                class="w-full py-2 px-3 bg-slate-800 hover:bg-slate-700 text-emerald-400 font-bold rounded-xl text-xs flex items-center justify-center gap-2 border border-slate-700 transition">
                <span>🌐 Public B2B Home Page</span>
              </button>

              <!-- Active Employee User Box -->
              <div class="p-3 bg-slate-950 rounded-xl border border-slate-800 space-y-2">
                <div class="flex items-center justify-between text-xs">
                  <span class="text-slate-400 text-[11px]">Logged Staff:</span>
                  <span class="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span>
                </div>
                <div class="text-xs font-bold text-white truncate">{{ getCurrentUser().name }}</div>
                <div class="flex items-center justify-between">
                  <span class="text-[10px] font-mono text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded border border-emerald-500/20 font-semibold">
                    {{ dataService.activeRole() }}
                  </span>
                </div>
              </div>

              <!-- Sidebar Admin Module Links -->
              <nav class="space-y-1 text-xs">
                <div class="px-2 py-1 text-[10px] font-bold text-slate-400 uppercase tracking-wider">ERP Main Operations</div>

                <button 
                  (click)="adminTab.set('dashboard')"
                  [class]="adminTab() === 'dashboard' ? 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-emerald-600 text-white font-bold transition shadow-sm' : 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-slate-300 hover:bg-slate-800 hover:text-white font-medium transition text-left'">
                  <span class="text-base">📊</span>
                  <span>Executive Dashboard</span>
                </button>

                <button 
                  (click)="adminTab.set('imports')"
                  [class]="adminTab() === 'imports' ? 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-emerald-600 text-white font-bold transition shadow-sm' : 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-slate-300 hover:bg-slate-800 hover:text-white font-medium transition text-left'">
                  <span class="text-base">📥</span>
                  <span>Import PO & LC Desk</span>
                </button>

                <button 
                  (click)="adminTab.set('exports')"
                  [class]="adminTab() === 'exports' ? 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-emerald-600 text-white font-bold transition shadow-sm' : 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-slate-300 hover:bg-slate-800 hover:text-white font-medium transition text-left'">
                  <span class="text-base">📤</span>
                  <span>Export Sales Orders</span>
                </button>

                <button 
                  (click)="adminTab.set('shipments')"
                  [class]="adminTab() === 'shipments' ? 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-emerald-600 text-white font-bold transition shadow-sm' : 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-slate-300 hover:bg-slate-800 hover:text-white font-medium transition text-left'">
                  <span class="text-base">🚢</span>
                  <span>Vessel Logistics</span>
                </button>

                <button 
                  (click)="adminTab.set('customs')"
                  [class]="adminTab() === 'customs' ? 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-emerald-600 text-white font-bold transition shadow-sm' : 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-slate-300 hover:bg-slate-800 hover:text-white font-medium transition text-left'">
                  <span class="text-base">📑</span>
                  <span>Customs & Duty</span>
                </button>

                <button 
                  (click)="adminTab.set('warehouse')"
                  [class]="adminTab() === 'warehouse' ? 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-emerald-600 text-white font-bold transition shadow-sm' : 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-slate-300 hover:bg-slate-800 hover:text-white font-medium transition text-left'">
                  <span class="text-base">🏬</span>
                  <span>Warehouse Bins</span>
                </button>

                <div class="px-2 pt-4 pb-1 text-[10px] font-bold text-slate-400 uppercase tracking-wider">ERP Master Setup</div>

                <button 
                  (click)="adminTab.set('products')"
                  [class]="adminTab() === 'products' ? 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-emerald-600 text-white font-bold transition shadow-sm' : 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-slate-300 hover:bg-slate-800 hover:text-white font-medium transition text-left'">
                  <span class="text-base">📦</span>
                  <span>Product SKU Master</span>
                </button>

                <button 
                  (click)="adminTab.set('suppliers')"
                  [class]="adminTab() === 'suppliers' ? 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-emerald-600 text-white font-bold transition shadow-sm' : 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-slate-300 hover:bg-slate-800 hover:text-white font-medium transition text-left'">
                  <span class="text-base">🏢</span>
                  <span>Suppliers & Buyers</span>
                </button>

                <button 
                  (click)="adminTab.set('accounts')"
                  [class]="adminTab() === 'accounts' ? 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-emerald-600 text-white font-bold transition shadow-sm' : 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-slate-300 hover:bg-slate-800 hover:text-white font-medium transition text-left'">
                  <span class="text-base">💰</span>
                  <span>Landed Costing</span>
                </button>

                <button 
                  (click)="adminTab.set('calculator')"
                  [class]="adminTab() === 'calculator' ? 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-emerald-600 text-white font-bold transition shadow-sm' : 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-slate-300 hover:bg-slate-800 hover:text-white font-medium transition text-left'">
                  <span class="text-base">🧮</span>
                  <span>Container Load Calc</span>
                </button>

                <button 
                  (click)="adminTab.set('roles')"
                  [class]="adminTab() === 'roles' ? 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg bg-emerald-600 text-white font-bold transition shadow-sm' : 'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-slate-300 hover:bg-slate-800 hover:text-white font-medium transition text-left'">
                  <span class="text-base">👥</span>
                  <span>Role Access Security</span>
                </button>
              </nav>

            </div>

            <div class="p-4 border-t border-slate-800 text-[11px] text-slate-400 space-y-1">
              <div class="flex justify-between"><span>ASP.NET API:</span><span class="text-emerald-400 font-bold">Online</span></div>
              <div class="flex justify-between"><span>Version:</span><span class="font-mono">v3.2 Keya ERP</span></div>
            </div>

          </aside>

          <!-- Right Admin Work Area Column -->
          <div class="flex-1 flex flex-col h-screen overflow-y-auto">

            <!-- Top Admin Utility Header Bar -->
            <header class="bg-white border-b border-slate-200 py-3 px-6 sticky top-0 z-30 flex items-center justify-between shadow-sm">
              <div class="flex items-center gap-3">
                <span class="text-xs font-mono text-slate-500">KEYA ERP ADMIN /</span>
                <h2 class="text-base font-bold text-slate-900 uppercase tracking-wide">{{ getAdminTabTitle() }}</h2>
              </div>

              <div class="flex items-center gap-4">

                <!-- Return to Public Home Page Link -->
                <button 
                  (click)="currentView.set('PUBLIC')"
                  class="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-lg border border-slate-300 transition">
                  🌐 Public B2B Home Page
                </button>

                <!-- Global Currency Selector -->
                <div class="flex items-center gap-2 bg-slate-100 px-3 py-1.5 rounded-lg border border-slate-200 text-xs">
                  <span class="text-slate-600 font-medium">Currency:</span>
                  <select 
                    [value]="dataService.currentCurrency().code"
                    (change)="onCurrencySelect($event)"
                    class="bg-transparent text-emerald-700 font-bold font-mono focus:outline-none cursor-pointer">
                    @for (c of dataService.currencies(); track c.code) {
                      <option [value]="c.code" class="bg-white text-slate-900">{{ c.flag }} {{ c.code }} ({{ c.symbol }})</option>
                    }
                  </select>
                </div>

                <!-- Role Switcher -->
                <div class="flex items-center gap-2 bg-slate-100 px-3 py-1.5 rounded-lg border border-slate-200 text-xs">
                  <span class="text-slate-600 font-medium">Staff Role:</span>
                  <select 
                    [value]="dataService.activeRole()"
                    (change)="onRoleSelect($event)"
                    class="bg-transparent text-slate-900 font-bold focus:outline-none cursor-pointer">
                    <option value="Admin" class="bg-white text-slate-900">Admin</option>
                    <option value="Export Manager" class="bg-white text-slate-900">Export Manager</option>
                    <option value="Import Manager" class="bg-white text-slate-900">Import Manager</option>
                    <option value="Accounts" class="bg-white text-slate-900">Accounts</option>
                    <option value="Warehouse" class="bg-white text-slate-900">Warehouse</option>
                    <option value="Management" class="bg-white text-slate-900">Executive Board</option>
                  </select>
                </div>

              </div>
            </header>

            <!-- Dynamic Admin Content View -->
            <main class="p-6 flex-1 bg-slate-50">
              @if (adminTab() === 'dashboard') { <app-erp-dashboard></app-erp-dashboard> }
              @if (adminTab() === 'roles') { <app-role-management></app-role-management> }
              @if (adminTab() === 'products') { <app-product-management></app-product-management> }
              @if (adminTab() === 'suppliers') { <app-supplier-management></app-supplier-management> }
              @if (adminTab() === 'imports') { <app-import-management></app-import-management> }
              @if (adminTab() === 'shipments') { <app-shipment-tracker></app-shipment-tracker> }
              @if (adminTab() === 'customs') { <app-customs-docs></app-customs-docs> }
              @if (adminTab() === 'warehouse') { <app-warehouse-inventory></app-warehouse-inventory> }
              @if (adminTab() === 'exports') { <app-export-management></app-export-management> }
              @if (adminTab() === 'accounts') { <app-accounts-costing></app-accounts-costing> }
              @if (adminTab() === 'calculator') { <app-rfq-calculator></app-rfq-calculator> }
            </main>

          </div>

        </div>
      }

    </div>
  `
})
export class AppComponent {
  dataService = inject(ExportImportDataService);

  // Dual System View State: PUBLIC (Home Page) vs ADMIN (Separate Internal ERP Panel)
  currentView = signal<'PUBLIC' | 'ADMIN'>('PUBLIC');

  // Active Sidebar Tab inside Admin Panel
  adminTab = signal<AdminSidebarTab>('dashboard');

  getCurrentUser() {
    const role = this.dataService.activeRole();
    const found = this.dataService.users().find(u => u.role === role);
    return found || this.dataService.users()[0];
  }

  getAdminTabTitle(): string {
    const titles: Record<AdminSidebarTab, string> = {
      dashboard: 'Executive Dashboard & BI Reports',
      roles: 'User & Role Security Matrix',
      products: 'Product Master Catalog & SKU Data',
      suppliers: 'Verified Suppliers & Buyer Accounts',
      imports: 'Import Purchase Orders & LC Lifecycle',
      shipments: 'Vessel Cargo & Container Tracking',
      customs: 'Customs Declarations & Duty Clearance',
      warehouse: 'Warehouse Stock Balance & Bin Management',
      exports: 'Export Sales Orders & Commercial Invoicing',
      accounts: 'Accounts & Landed Costing Engine',
      calculator: 'Container Load Capacity Calculator'
    };
    return titles[this.adminTab()];
  }

  onCurrencySelect(event: Event) {
    const code = (event.target as HTMLSelectElement).value;
    this.dataService.setCurrency(code);
  }

  onRoleSelect(event: Event) {
    const role = (event.target as HTMLSelectElement).value as UserRole;
    this.dataService.setRole(role);
  }
}
